WITH FilteredStores AS (SELECT *, COALESCE(sqft, 0) AS sqft_filled FROM stores WHERE store_name LIKE 'Sia%' AND (UPPER(TRIM(store_name)) = 'RIVERSIDE' OR region IN ('East', 'Central', 'West'))), region_summary AS (SELECT region, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(city))) AS city_values, COUNT(sqft_filled) AS sqft_filled_count FROM FilteredStores GROUP BY region) SELECT * FROM region_summary ORDER BY city_values DESC;
